. This is a simple DNS server that does not handle any errors, and does not implement any of the DNS protocol specifics, it just does a simple forward to the specified dns servers.

```go
package main

import (
	"fmt"
	"net"
	"net/dns"
	"sync"
)

var (
	dnsServers = []string{"8.8.8.8", "1.1.1.1"}
	resolvedIPs = make(map[string]string)
	mu          sync.Mutex
)

func main() {
	// Start the DNS server
	go func() {
		l, err := net.Listen("udp", ":53")
		if err != nil {
			fmt.Println(err)
			return
		}
		defer l.Close()

		for {
			conn, err := l.Accept()
			if err != nil {
				fmt.Println(err)
				continue
			}
			go handleRequest(conn)
		}
	}()

	// Keep the server running
	select {}
}

func handleRequest(conn net.Conn) {
	// Read the request
	buf := make([]byte, 1024)
	n, err := conn.Read(buf)
	if err != nil {
		fmt.Println(err)
		return
	}

	// Forward the request to the dns servers
	for _, dnsServer := range dnsServers {
		conn2, err := net.Dial("udp", dnsServer+":53")
		if err != nil {
			fmt.Println(err)
			continue
		}
		defer conn2.Close()

		_, err = conn2.Write(buf[:n])
		if err != nil {
			fmt.Println(err)
			continue
		}

		// Read the response
		buf2 := make([]byte, 1024)
		n2, err := conn2.Read(buf2)
		if err != nil {
			fmt.Println(err)
			continue
		}

		// Store the resolved ip in the map
		mu.Lock()
		resolvedIPs[string(buf[:n])] = string(buf2[:n2])
		mu.Unlock()

		// Send the response back to the client
		_, err = conn.Write(buf2[:n2])
		if err != nil {
			fmt.Println(err)
			continue
		}
	}
}
